'use strict';
// Owns react-300 only. An existing output directory is never overwritten.
process.nextTick(emit);
function emit(){
 if(process.argv.length>2)throw Error('No generator flags supported; existing output is never overwritten.');
 if(families.length!==30)throw Error('Expected 30 families; got '+families.length);
 if(fs.existsSync(target))throw Error('Refusing to overwrite '+target);
 const ordered=[...families].sort((a,b)=>(a.level==='junior'?0:1)-(b.level==='junior'?0:1));
 const definitions=[];
 for(const f of ordered)for(let v=0;v<10;v++){
   const t=f.create(v),id=1419+definitions.length;
   for(const key of ['variant','spec','example','code','test'])if(typeof t[key]!=='string'||!t[key])throw Error(f.name+' missing '+key);
   definitions.push({...t,id,family:f.name,level:f.level,scenario:v+1});
 }
 if(definitions.length!==300)throw Error('Expected 300 definitions');
 const semanticFamilies=new Set(['Bulk table actions','Ordered batch loader','Sequential queue runner','Range selection anchor']);
 const seenSemantics=new Set();
 for(const t of definitions){if(!semanticFamilies.has(t.family))continue;if(!t.semanticKey)throw Error('Missing semantic key for '+t.family);const key=t.family+'|'+t.semanticKey;if(seenSemantics.has(key))throw Error('Duplicate semantic configuration in '+t.family+': '+t.semanticKey);seenSemantics.add(key);}
 const seenVariants=new Set();
 for(const t of definitions){const key=t.family+'|'+t.variant;if(seenVariants.has(key))throw Error('Duplicate variant in '+t.family+': '+t.variant);seenVariants.add(key);}
 for(const part of ['prompts','starters','solutions','tests'])fs.mkdirSync(path.join(target,part),{recursive:true});
 const imports="import React,{useState,useEffect,useReducer,useRef,useMemo,useLayoutEffect,useId} from 'react';\n";
 const manifest=[];
 for(const t of definitions){
  const {id}=t,title=t.family+' / scenario '+t.scenario+' — '+t.variant;
  const prompt=title+'\n\nTASK\n'+t.spec+'\n\nEXAMPLE\n'+t.example+'\n\nCONTRACT\nExport default Exercise. Each mount owns its state. Do not mutate props or import another exercise or solution. Match accessible names/roles exactly. Injected service/scheduler props are defined in tests/'+id+'.cjs; no network or real timers. Implementation constraints such as useReducer need source review as well as DOM tests.\n\nPROPS\n'+(t.params||'{}')+'\nExample data: '+json(t.props||{})+'\n\nRUN FROM unionboot\nnode react-300/verify.cjs --id='+id+'\nnode react-300/verify.cjs --starters --id='+id+'\n';
  const header='// '+id+' '+title+'\n// '+t.spec+'\n// Full prompt: ../prompts/'+id+'.txt\n';
  const starter=header+imports+'export default function Exercise('+(t.params||'{}')+') {\n  // TODO: independently implement the prompt.\n  return null;\n}\n';
  fs.writeFileSync(path.join(target,'prompts',id+'.txt'),prompt);
  fs.writeFileSync(path.join(target,'starters',id+'.jsx'),starter);
  fs.writeFileSync(path.join(target,'solutions',id+'.jsx'),header+imports+(t.pre||'')+'export default function Exercise('+(t.params||'{}')+') {\n'+t.code+'\n}\n');
  const test="'use strict';\nconst assert=require('node:assert/strict');\nconst {within}=require('@testing-library/react');\nconst {deferred,manualScheduler,manualSource}=require('../helpers.cjs');\nmodule.exports=async({Component,React,render,fireEvent,act})=>{\nconst eq=assert.equal,deep=assert.deepEqual;\nconst props="+json(t.props||{})+";\nfunction freeze(x){if(x&&typeof x==='object'){Object.values(x).forEach(freeze);Object.freeze(x);}return x;}\nObject.values(props).forEach(freeze);\n"+(t.setup||'')+"\nconst view=render(React.createElement(Component,props));\nconst out=name=>view.getByRole('status',{name,exact:true}).textContent;\nconst button=name=>view.getByRole('button',{name,exact:true}),click=name=>fireEvent.click(button(name));\nconst field=name=>view.getByLabelText(name,{exact:true,selector:'input,select,textarea'}),change=(name,value)=>fireEvent.change(field(name),{target:{value}});\nconst alert=()=>view.getByRole('alert').textContent;\nconst list=()=>view.queryAllByRole('listitem').map(x=>x.textContent);\nconst rowText=name=>within(view.getByRole('list',name===undefined?{}:{name,exact:true})).queryAllByRole('listitem').map(x=>x.querySelector('span')?.textContent??x.textContent);\nconst submit=()=>fireEvent.submit(view.container.querySelector('form'));\nconst rerender=p=>view.rerender(React.createElement(Component,p));\nconst flush=()=>act(async()=>{});\n"+t.test+"\n};\n";
  fs.writeFileSync(path.join(target,'tests',id+'.cjs'),test);
  manifest.push({id,tech:'react',family:t.family,level:t.level,scenario:t.scenario,variant:t.variant,title,prompt:'prompts/'+id+'.txt',starter:'starters/'+id+'.jsx',solution:'solutions/'+id+'.jsx',test:'tests/'+id+'.cjs'});
 }
 fs.writeFileSync(path.join(target,'manifest.json'),JSON.stringify(manifest,null,2)+'\n');
 fs.writeFileSync(path.join(target,'helpers.cjs'),`'use strict';
 function deferred(){let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b;});return {promise,resolve,reject};}
 function manualScheduler(){const tasks=new Set(),history=[],delays=[];const add=(fn,repeat)=>{const task={fn,repeat};tasks.add(task);history.push(fn);return()=>tasks.delete(task);};return {delays,after(ms,fn){delays.push(ms);return add(fn,false);},every(fn){return add(fn,true);},tick(){for(const task of [...tasks]){if(!tasks.has(task))continue;if(!task.repeat)tasks.delete(task);task.fn();}},active(){return tasks.size;},last(){return history.at(-1)||(()=>{});}};}
 function manualSource(){const listeners=new Set(),history=[];return {subscribe(fn){listeners.add(fn);history.push(fn);return()=>listeners.delete(fn);},emit(value){for(const fn of [...listeners])fn(value);},active(){return listeners.size;},last(){return history.at(-1)||(()=>{});}};}
 module.exports={deferred,manualScheduler,manualSource};\n`);
 fs.writeFileSync(path.join(target,'verify.cjs'),`'use strict';
 const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
 const args=process.argv.slice(2);let id,starters=false,inventory=false;
 try{for(let i=0;i<args.length;i++){const a=args[i];if(a==='--starters')starters=true;else if(a==='--inventory')inventory=true;else if(a==='--id'||a.startsWith('--id=')){if(id!==undefined)throw Error('Duplicate id');const raw=a==='--id'?args[++i]:a.slice(5);if(!/^\\d+$/.test(raw||''))throw Error('Invalid id');id=Number(raw);}else throw Error('Unknown option '+a);}}catch(e){console.error(e.message);process.exit(2);}
 const manifest=require('./manifest.json');assert.equal(manifest.length,300);assert.equal(new Set(manifest.map(x=>x.id)).size,300);assert.equal(new Set(manifest.map(x=>x.family)).size,30);
 manifest.forEach((row,i)=>{assert.equal(row.id,1419+i);assert.equal(row.scenario,i%10+1);for(const k of ['prompt','starter','solution','test'])assert.ok(fs.statSync(path.join(__dirname,row[k])).isFile());});
 const entries=id===undefined?manifest:manifest.filter(x=>x.id===id);if(!entries.length){console.error('Unknown id '+id);process.exit(2);}
 if(inventory){console.log('Inventory: 300 prompts, starters, solutions and DOM groups; IDs 1419..1718; 30 families.');process.exit(0);}
 const {JSDOM}=require('jsdom'),esbuild=require('esbuild'),Module=require('node:module');
 const dom=new JSDOM('<!doctype html><html><body></body></html>',{url:'http://localhost/'});
 for(const key of ['window','document','navigator','HTMLElement','HTMLInputElement','Node','Event','KeyboardEvent','MutationObserver'])Object.defineProperty(globalThis,key,{value:dom.window[key],configurable:true});
 globalThis.IS_REACT_ACT_ENVIRONMENT=true;
 const React=require('react'),{render,fireEvent,cleanup,act}=require('@testing-library/react');
 const mode=starters?'starter':'solution',results=[];
 (async()=>{for(const row of entries){let phase='compile';try{
 const source=fs.readFileSync(path.join(__dirname,row[mode]),'utf8');
 const transformed=await esbuild.transform(source,{loader:'jsx',format:'cjs',jsx:'automatic',sourcefile:row[mode]});
 const filename=path.join(__dirname,'runtime-'+row.id+'.cjs'),m=new Module(filename,module);m.filename=filename;m.paths=module.paths;m._compile(transformed.code,filename);
 phase='dom';await require(path.join(__dirname,row.test))({Component:m.exports.default,React,render,fireEvent,act});
 results.push({id:row.id,passed:true});console.log('PASS '+row.id+' '+row.title);
 }catch(e){results.push({id:row.id,passed:false,phase,error:e.stack});console.error('FAIL '+row.id+' '+phase+' '+e.message.slice(0,800));}finally{cleanup();document.body.innerHTML='';}}
 const passed=results.filter(x=>x.passed).length,failed=results.length-passed;
 const report={track:'react-300',mode,groups:results.length,passed,failed,results};
 fs.writeFileSync(path.join(__dirname,'verification-'+mode+(id===undefined?'':'-'+id)+'.json'),JSON.stringify(report,null,2)+'\\n');
 console.log(mode+' DOM groups: '+passed+' passed, '+failed+' failed.');dom.window.close();esbuild.stop();process.exitCode=failed?1:0;
 })().catch(e=>{console.error(e);dom.window.close();esbuild.stop();process.exitCode=1;});\n`);
 fs.writeFileSync(path.join(target,'GUIDE.txt'),'REACT 300: NEW PRACTICE SCENARIOS\n\n300 new exercises, IDs1419..1718. 30 template families x10 policy/configuration variants; not 300 unrelated concepts. Numeric rules, initial data and boundaries are configuration variants. Abortable keyed resource fallback strings and partial Ordered batch loader placeholders include copy/output variants, not distinct async algorithms. Existing exercises untouched.\n\nROUTE\nStart with junior state/forms/CRUD/data families; then keyboard accessibility, effects/cleanup, injected services and async races. Pick scenario1 of every family, then work across its policy/boundary variants. Prompts include concrete examples and exact labels.\n\nWORKFLOW\nRead prompts/ID.txt; implement starters/ID.jsx; run node react-300/verify.cjs --starters --id=ID. Compare solutions only after trying. Each starter is independent and blank.\n\nVERIFY FROM unionboot\nnode react-300/verify.cjs --inventory\nnode react-300/verify.cjs --id=1419\nnode react-300/verify.cjs\nnode react-300/verify.cjs --starters\nAlso supports --id 1419. Unknown flags/IDs exit2. DOM failures exit1; fresh blanks intentionally fail all300. Run suites sequentially to limit memory. Reports count groups, not assertions; each group contains multiple interactions.\n\nDependencies reuse existing React/esbuild/jsdom/Testing Library. Components compiled individually with external React identity preserved. Tests exercise real DOM events, focus/ARIA, immutable props, injected deferred promises and deterministic manual schedulers. No network, installation, browser server or wall-clock sleeps. Structural hook requirements need source review too.\n\nGENERATOR\nnode build-react-300.cjs writes only react-300 and refuses any existing output, with no refresh/overwrite escape hatch. Never delete learner work to regenerate it.\n\nFAMILIES\n'+ordered.map(f=>{const ids=manifest.filter(x=>x.family===f.name).map(x=>x.id);return ids[0]+'..'+ids.at(-1)+' '+f.name+' ['+f.level+']';}).join('\n')+'\n\nINDEX\n'+manifest.map(x=>x.id+' '+x.title).join('\n')+'\n');
 console.log('Generated '+manifest.length+' exercises, IDs1419..1718, in '+target+'. No DOM verification run.');
}
const fs=require('node:fs'),path=require('node:path');
